-- A trigger, as mysqldump emits one: a DELIMITER block whose body contains
-- semicolons. The driver cannot create it; it must be reported as ONE failed
-- statement, not shatter into fragments that partially execute.
DELIMITER ;;
/*!50003 CREATE*/ /*!50003 TRIGGER `after_insert_post` AFTER INSERT ON `wp_posts`
 FOR EACH ROW BEGIN
    IF NEW.post_title LIKE '%x%' THEN
        SET @n = 1;
        INSERT INTO `wp_options` (`option_name`, `option_value`, `autoload`) VALUES ('trigger_ran', '1', 'yes');
    END IF;
 END */;;
DELIMITER ;

